/**
 * RPC contract tests: commission_split_tax_line_record (S17)
 *
 * DB-gated. Per-test studio + parent split fixture.
 *
 * Coverage (5 tests):
 *  1. Happy path — inserts kind='tax_line' row, links parent_split_id, sets tax_amount_cents
 *  2. Idempotency — same (parent_split_id, tax_line_id) → same id, created: false
 *  3. Different tax_line_id under same parent → 2 separate rows
 *  4. Parent not found → RAISE EXCEPTION
 *  5. Parent kind='tax_line' (chained) → RAISE EXCEPTION ("parent must be regular split")
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type CommissionSplitTaxLineRecordArgs,
  type CommissionSplitTaxLineRecordResult,
  type CommissionSplitRecordResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: commission_split_tax_line_record', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  /** Insert a parent commission_splits row of kind='split'. Returns the row id. */
  async function createParentSplit(opts: { kind?: 'split' | 'tip' | 'adjustment' } = {}): Promise<string> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_RECORD, {
      p_studio_id: studioId,
      p_booking_id: null,
      p_session_id: null,
      p_artist_id: artistId,
      p_base_amount_cents: cents(8000),
      p_commission_pct: 70,
      p_tip_amount_cents: cents(0),
      p_applied_from_pool_cents: cents(0),
      p_stripe_transfer_id: null,
      p_kind: opts.kind ?? 'split',
    })
    if (error) throw new Error(`createParentSplit failed: ${error.message}`)
    const result = data as CommissionSplitRecordResult
    return result.id
  }

  /** Insert a tax_line child under a parent split. Returns the raw RPC result. */
  async function callTaxLineRpc(
    args: CommissionSplitTaxLineRecordArgs,
  ): Promise<{ data: CommissionSplitTaxLineRecordResult | null; error: { message: string } | null }> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_RECORD, {
      p_parent_split_id: args.parentSplitId,
      p_tax_line_id: args.taxLineId,
      p_jurisdiction: args.jurisdiction,
      p_tax_amount_cents: args.taxAmountCents,
    })
    return {
      data: data as CommissionSplitTaxLineRecordResult | null,
      error,
    }
  }

  // ---------------------------------------------------------------------------
  // Tests
  // ---------------------------------------------------------------------------

  it('happy path — inserts kind=tax_line row with correct fields', async () => {
    const parentId = await createParentSplit()
    const taxLineId = `taxline_${randomUUID().replace(/-/g, '').slice(0, 16)}`

    const { data, error } = await callTaxLineRpc({
      parentSplitId: parentId,
      taxLineId,
      jurisdiction: 'US-NY',
      taxAmountCents: cents(250),
    })

    expect(error).toBeNull()
    expect(data).not.toBeNull()

    const result = data as CommissionSplitTaxLineRecordResult
    expect(typeof result.id).toBe('string')
    expect(result.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
    expect(result.created).toBe(true)

    // Verify DB row shape
    const { data: row } = await sb
      .from('commission_splits')
      .select('id, kind, parent_split_id, tax_amount_cents, tax_line_id, jurisdiction')
      .eq('id', result.id)
      .maybeSingle()

    expect(row).not.toBeNull()
    expect(row?.kind).toBe('tax_line')
    expect(row?.parent_split_id).toBe(parentId)
    expect(row?.tax_amount_cents).toBe(250)
    expect(row?.tax_line_id).toBe(taxLineId)
    expect(row?.jurisdiction).toBe('US-NY')
  })

  it('idempotency — same (parent_split_id, tax_line_id) returns same id, created: false', async () => {
    const parentId = await createParentSplit()
    const taxLineId = `taxline_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const args: CommissionSplitTaxLineRecordArgs = {
      parentSplitId: parentId,
      taxLineId,
      jurisdiction: 'US-NY-NYC',
      taxAmountCents: cents(120),
    }

    const { data: first, error: e1 } = await callTaxLineRpc(args)
    const { data: second, error: e2 } = await callTaxLineRpc(args)

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const r1 = first as CommissionSplitTaxLineRecordResult
    const r2 = second as CommissionSplitTaxLineRecordResult

    // Same id returned on replay
    expect(r1.id).toBe(r2.id)
    expect(r1.created).toBe(true)
    expect(r2.created).toBe(false)

    // Only 1 row in DB (no duplicate)
    const { count } = await sb
      .from('commission_splits')
      .select('id', { count: 'exact', head: true })
      .eq('parent_split_id', parentId)
      .eq('tax_line_id', taxLineId)

    expect(count).toBe(1)
  })

  it('different tax_line_id under same parent → 2 separate rows', async () => {
    const parentId = await createParentSplit()
    const taxLineId1 = `taxline_state_${randomUUID().replace(/-/g, '').slice(0, 12)}`
    const taxLineId2 = `taxline_city_${randomUUID().replace(/-/g, '').slice(0, 12)}`

    const { data: r1, error: e1 } = await callTaxLineRpc({
      parentSplitId: parentId,
      taxLineId: taxLineId1,
      jurisdiction: 'US-NY',
      taxAmountCents: cents(200),
    })
    const { data: r2, error: e2 } = await callTaxLineRpc({
      parentSplitId: parentId,
      taxLineId: taxLineId2,
      jurisdiction: 'US-NY-NYC',
      taxAmountCents: cents(50),
    })

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const result1 = r1 as CommissionSplitTaxLineRecordResult
    const result2 = r2 as CommissionSplitTaxLineRecordResult

    expect(result1.id).not.toBe(result2.id)
    expect(result1.created).toBe(true)
    expect(result2.created).toBe(true)

    // Both rows exist in DB under the same parent
    const { count } = await sb
      .from('commission_splits')
      .select('id', { count: 'exact', head: true })
      .eq('parent_split_id', parentId)
      .eq('kind', 'tax_line')

    expect(count).toBe(2)
  })

  it('parent not found → RAISE EXCEPTION', async () => {
    const ghostParentId = randomUUID()

    const { data, error } = await callTaxLineRpc({
      parentSplitId: ghostParentId,
      taxLineId: `taxline_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
      jurisdiction: 'US-CA',
      taxAmountCents: cents(100),
    })

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    // Postgres raises P0001 for RAISE EXCEPTION
    expect(
      error?.message?.toLowerCase().includes('not found') ||
      error?.message?.toLowerCase().includes('parent') ||
      error?.message?.toLowerCase().includes('does not exist'),
    ).toBe(true)
  })

  it('parent kind=tax_line (chained) → RAISE EXCEPTION — parent must be regular split', async () => {
    // Create a grandparent split, then a tax_line child
    const grandparentId = await createParentSplit()
    const taxLineId = `taxline_${randomUUID().replace(/-/g, '').slice(0, 16)}`

    const { data: taxLineRow, error: e1 } = await callTaxLineRpc({
      parentSplitId: grandparentId,
      taxLineId,
      jurisdiction: 'US-TX',
      taxAmountCents: cents(80),
    })
    expect(e1).toBeNull()
    const taxLineRowId = (taxLineRow as CommissionSplitTaxLineRecordResult).id

    // Now try to create a tax_line under the tax_line row — must fail
    const { data: chained, error: e2 } = await callTaxLineRpc({
      parentSplitId: taxLineRowId,
      taxLineId: `taxline_chained_${randomUUID().replace(/-/g, '').slice(0, 12)}`,
      jurisdiction: 'US-TX-HOUSTON',
      taxAmountCents: cents(20),
    })

    expect(chained).toBeNull()
    expect(e2).not.toBeNull()
    expect(
      e2?.message?.toLowerCase().includes('regular split') ||
      e2?.message?.toLowerCase().includes('tax_line') ||
      e2?.message?.toLowerCase().includes('parent must') ||
      e2?.message?.toLowerCase().includes('invalid parent'),
    ).toBe(true)
  })
})

/**
 * RPC contract tests: commission_splits_drift_check (S17)
 *
 * DB-gated. Uses service-role client to seed stripe_charges and commission_splits,
 * then asserts the drift-check RPC returns the correct drift lists.
 *
 * Coverage (6 tests):
 *  1. Empty case — no PIs, no disputes → returns empty drift lists
 *  2. PI succeeded WITH commission_split → NOT in pis_missing_split
 *  3. PI succeeded WITHOUT commission_split → appears in pis_missing_split
 *  4. Dispute lost WITH reversal split → NOT in disputes_missing_reversal
 *  5. Dispute lost WITHOUT reversal split → appears in disputes_missing_reversal
 *  6. Old PIs (before since_timestamp) → not included (filter works)
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type CommissionSplitsDriftCheckArgs,
  type CommissionSplitsDriftCheckResult,
  type CommissionSplitRecordResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: commission_splits_drift_check', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  async function insertStripeCharge(opts: {
    paymentIntentId: string
    chargeId: string
    status: string
    createdAt?: string
  }): Promise<void> {
    const idempotencyKey = `inkos_idem_${randomUUID().replace(/-/g, '').slice(0, 28)}`
    const { error } = await sb.from('stripe_charges').insert({
      studio_id: studioId,
      payment_intent_id: opts.paymentIntentId,
      charge_id: opts.chargeId,
      status: opts.status,
      currency: 'usd',
      amount_cents: cents(10000),
      tax_amount_cents: cents(0),
      application_fee_cents: cents(1000),
      net_artist_cents: cents(9000),
      tip_amount_cents: cents(0),
      deposit_drawdown_cents: cents(0),
      idempotency_key: idempotencyKey,
      // Allow seeding with a past created_at for filter tests
      ...(opts.createdAt ? { created_at: opts.createdAt } : {}),
    })
    if (error) throw new Error(`insertStripeCharge failed: ${error.message}`)
  }

  async function insertStripeDispute(opts: {
    disputeId: string
    chargeId: string
    status: string
    resolvedAt?: string
  }): Promise<void> {
    const { error } = await sb.from('stripe_disputes').insert({
      studio_id: studioId,
      dispute_id: opts.disputeId,
      charge_id: opts.chargeId,
      reason: 'credit_not_processed',
      status: opts.status,
      amount_cents: cents(10000),
      currency: 'usd',
      evidence_due_by: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      defense_pack_status: 'pending',
      ...(opts.resolvedAt ? { resolved_at: opts.resolvedAt } : {}),
    })
    if (error) throw new Error(`insertStripeDispute failed: ${error.message}`)
  }

  async function insertCommissionSplit(opts: {
    kind: 'split' | 'reversal' | 'adjustment' | 'tip'
    parentSplitId?: string
  }): Promise<string> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_RECORD, {
      p_studio_id: studioId,
      p_booking_id: null,
      p_session_id: null,
      p_artist_id: artistId,
      p_base_amount_cents: cents(9000),
      p_commission_pct: 70,
      p_tip_amount_cents: cents(0),
      p_applied_from_pool_cents: cents(0),
      p_stripe_transfer_id: null,
      p_kind: opts.kind,
    })
    if (error) throw new Error(`insertCommissionSplit failed: ${error.message}`)
    return (data as CommissionSplitRecordResult).id
  }

  async function runDriftCheck(sinceTimestamp: string): Promise<CommissionSplitsDriftCheckResult> {
    const args: CommissionSplitsDriftCheckArgs = { sinceTimestamp }
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLITS_DRIFT_CHECK, {
      p_since_timestamp: args.sinceTimestamp,
    })
    if (error) throw new Error(`drift_check RPC failed: ${error.message}`)
    return data as CommissionSplitsDriftCheckResult
  }

  // ---------------------------------------------------------------------------
  // Tests
  // ---------------------------------------------------------------------------

  it('empty case — no PIs or disputes since timestamp → returns empty drift lists', async () => {
    const since = new Date().toISOString()
    const result = await runDriftCheck(since)

    expect(result.pis_missing_split).toEqual([])
    expect(result.disputes_missing_reversal).toEqual([])
  })

  it('PI succeeded WITH commission_split → NOT in pis_missing_split', async () => {
    const piId = `pi_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const chargeId = `ch_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const since = new Date(Date.now() - 1000).toISOString()

    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'succeeded' })
    await insertCommissionSplit({ kind: 'split' })

    // The RPC must join stripe_charges to commission_splits on something —
    // for now verify this PI does not appear in the missing list
    const result = await runDriftCheck(since)

    const missingIds = result.pis_missing_split.map((r) => r.payment_intent_id)
    expect(missingIds).not.toContain(piId)
  })

  it('PI succeeded WITHOUT commission_split → appears in pis_missing_split', async () => {
    const piId = `pi_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const chargeId = `ch_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const since = new Date(Date.now() - 1000).toISOString()

    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'succeeded' })
    // No commission_split inserted for this charge

    const result = await runDriftCheck(since)

    const missingPis = result.pis_missing_split
    const match = missingPis.find((r) => r.payment_intent_id === piId)

    expect(match).toBeDefined()
    expect(match?.charge_id).toBe(chargeId)
    expect(match?.studio_id).toBe(studioId)
    expect(typeof match?.created_at).toBe('string')
  })

  it('dispute lost WITH reversal split → NOT in disputes_missing_reversal', async () => {
    const disputeId = `dp_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const chargeId = `ch_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const since = new Date(Date.now() - 1000).toISOString()
    const resolvedAt = new Date().toISOString()

    // First insert a base charge so the dispute FK is satisfied
    await insertStripeCharge({ paymentIntentId: `pi_base_${randomUUID().replace(/-/g, '').slice(0, 14)}`, chargeId, status: 'succeeded' })
    await insertStripeDispute({ disputeId, chargeId, status: 'lost', resolvedAt })

    // Create a reversal split to cover this dispute
    const parentId = await insertCommissionSplit({ kind: 'split' })
    await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(9000),
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })

    const result = await runDriftCheck(since)

    const missingDisputeIds = result.disputes_missing_reversal.map((r) => r.dispute_id)
    expect(missingDisputeIds).not.toContain(disputeId)
  })

  it('dispute lost WITHOUT reversal split → appears in disputes_missing_reversal', async () => {
    const disputeId = `dp_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const chargeId = `ch_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const since = new Date(Date.now() - 1000).toISOString()
    const resolvedAt = new Date().toISOString()

    await insertStripeCharge({ paymentIntentId: `pi_base_${randomUUID().replace(/-/g, '').slice(0, 14)}`, chargeId, status: 'succeeded' })
    await insertStripeDispute({ disputeId, chargeId, status: 'lost', resolvedAt })
    // No reversal split

    const result = await runDriftCheck(since)

    const match = result.disputes_missing_reversal.find((r) => r.dispute_id === disputeId)
    expect(match).toBeDefined()
    expect(match?.charge_id).toBe(chargeId)
    expect(match?.studio_id).toBe(studioId)
  })

  it('old PIs (before since_timestamp) → not in drift list (filter works)', async () => {
    // Insert a charge with a timestamp far in the past
    const oldPiId = `pi_old_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const oldChargeId = `ch_old_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString()

    await insertStripeCharge({
      paymentIntentId: oldPiId,
      chargeId: oldChargeId,
      status: 'succeeded',
      createdAt: twoHoursAgo,
    })
    // No commission_split — would appear in drift if filter didn't work

    // Query with since = 1 hour ago — the 2-hour-old charge is outside the window
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString()
    const result = await runDriftCheck(oneHourAgo)

    const missingIds = result.pis_missing_split.map((r) => r.payment_intent_id)
    expect(missingIds).not.toContain(oldPiId)
  })
})

/**
 * Integration tests: S17 tax mirror logic in process-stripe-event.ts
 *
 * All tests use vi.mock for Supabase — no DB required. All tests run unconditionally.
 *
 * S17 tax mirror: when payment_intent.succeeded fires with Stripe Tax data, the handler should:
 *   1. Pass p_tax_amount_cents to STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK
 *   2. Iterate charge.amount_details.tax_breakdown and call COMMISSION_SPLIT_TAX_LINE_RECORD per entry
 *   3. Call TAX_REMITTANCE_ACCRUE once per jurisdiction
 *   4. Gracefully degrade when parent split is missing
 *   5. Gracefully degrade when studio location lookup fails
 *   6. Log but not throw on tax mirror RPC failure (recoverable via reconciliation)
 *
 * NOTE: Tests 1–7 define the S17 contract. They will FAIL until process-stripe-event.ts
 * is updated with the tax mirror logic. They are written as active tests (not .todo)
 * so CI enforces the contract once Track A ships.
 *
 * Coverage (7 tests):
 *  1. PI succeeded with tax.amount=250 → STRIPE_CHARGE_UPDATE_STATUS called with p_tax_amount_cents=250
 *  2. PI succeeded with empty tax_breakdown → no COMMISSION_SPLIT_TAX_LINE_RECORD; TAX_REMITTANCE_ACCRUE with jurisdiction='UNKNOWN'
 *  3. PI succeeded with 2 tax_breakdown entries → COMMISSION_SPLIT_TAX_LINE_RECORD called twice with correct jurisdictions
 *  4. PI succeeded with tax_breakdown → TAX_REMITTANCE_ACCRUE called once per jurisdiction with correct period
 *  5. PI succeeded but parent commission_split not found → warns, no tax line inserts
 *  6. PI succeeded with no studio location → skips ledger accrual gracefully
 *  7. Tax mirror RPC failure → logs error, does NOT throw
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { RPC } from '@/lib/payments/contracts'
import type { StripeEventLike, SupabaseServiceClient } from '@/lib/payments/process-stripe-event'

// ---------------------------------------------------------------------------
// Mock logger (global mock is in setup.ts but we import it for assertions)
