interface TaxBreakdownEntry {
  amount: number
  jurisdiction: { state?: string; country: string; county?: string; city?: string }
  sourcing: 'origin' | 'destination'
  tax_rate_details?: { percentage_decimal?: string; tax_type?: string }
  display_name: string
