// ---------------------------------------------------------------------------
// Supabase mock factory — mirrors the pattern from process-stripe-event-saga.test.ts
// ---------------------------------------------------------------------------

type RpcHandler = (fn: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: null | { message: string } }>

function makeSupabaseMock(
  rpcHandler?: RpcHandler,
  chargeData?: Record<string, unknown> | null,
  splitData?: Record<string, unknown> | null,
  locationData?: Record<string, unknown> | null,
): SupabaseServiceClient {
  const defaultHandler: RpcHandler = async () => ({ data: { id: 'mock-result' }, error: null })
  const handler = rpcHandler ?? defaultHandler

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => handler(fn, args))

  // from() stub — handles stripe_charges, commission_splits, and locations selects
  const fromFn = vi.fn((table: string) => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return {
              data: chargeData ?? {
                studio_id: 'studio-test-001',
                net_artist_cents: 9000,
                application_fee_cents: 1000,
                tip_amount_cents: 0,
                deposit_drawdown_cents: 0,
                transfer_id: null,
                tax_amount_cents: 250,
              },
              error: null,
            }
          }
          if (table === 'commission_splits') {
            return { data: splitData ?? { id: 'split-test-001' }, error: null }
          }
          if (table === 'locations' || table === 'studio_locations') {
            return { data: locationData ?? { id: 'loc-test-001' }, error: null }
          }
          return { data: { studio_id: 'studio-test-001' }, error: null }
        }),
        single: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return {
              data: chargeData ?? {
                studio_id: 'studio-test-001',
                net_artist_cents: 9000,
                application_fee_cents: 1000,
                tip_amount_cents: 0,
                deposit_drawdown_cents: 0,
                transfer_id: null,
                tax_amount_cents: 250,
              },
              error: null,
            }
          }
          return { data: null, error: null }
        }),
      })),
    })),
    update: vi.fn(() => ({
      eq: vi.fn(async () => ({ error: null })),
    })),
  }))

  return {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: { bind: vi.fn(() => fromFn) },
  } as unknown as SupabaseServiceClient
}

// ---------------------------------------------------------------------------
// Event factory — includes S17 tax fields on the PI object
// ---------------------------------------------------------------------------

function makePaymentIntentSucceededEvent(opts: {
  taxAmount?: number
  taxBreakdown?: TaxBreakdownEntry[]
  metadata?: Record<string, string>
}): StripeEventLike {
  return {
    id: `evt_pi_${Math.random().toString(36).slice(2, 10)}`,
    type: 'payment_intent.succeeded',
    data: {
      object: {
        id: 'pi_test_001',
        latest_charge: 'ch_test_001',
        metadata: {
          inkos_studio_id: 'studio-test-001',
          inkos_artist_id: 'artist-test-001',
          inkos_booking_id: 'booking-test-001',
          ...opts.metadata,
        },
        amount_details: {
          tax: opts.taxAmount !== undefined ? { amount: opts.taxAmount } : undefined,
          breakdown: opts.taxBreakdown ?? [],
        },
      },
    },
  }
}

