function makeSupabaseMock(
  rpcHandler?: RpcHandler,
  chargeData?: Record<string, unknown> | null,
  splitData?: Record<string, unknown> | null,
  locationData?: Record<string, unknown> | null,
): SupabaseServiceClient {
  const defaultHandler: RpcHandler = async () => ({ data: { id: 'mock-result' }, error: null })
  const handler = rpcHandler ?? defaultHandler

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => handler(fn, args))

  // The production code uses TWO patterns for `from`:
  //
  //   1. Direct cast: `const fromUntyped = supabase.from as unknown as (table: string) => ...`
  //      Used in handlePaymentIntentStatusChange for stripe_charges reads.
  //
  //   2. Bind cast: `supabase.from.bind(supabase) as unknown as UntypedFrom`
  //      Used in handleChargeRefunded and resolveStudioIdFromCharge.
  //
  // The mock must satisfy BOTH: fromFn itself must be a callable function AND carry a .bind() method.
  // We use Object.assign to attach bind directly on the callable vi.fn().

  const defaultChargeData = chargeData !== null
    ? (chargeData ?? {
        studio_id: 'studio-test-001',
        net_artist_cents: 9000,
        application_fee_cents: 1000,
        tip_amount_cents: 0,
        deposit_drawdown_cents: 0,
        transfer_id: null,
        tax_amount_cents: 250,
      })
    : null

  const fromFn = vi.fn((table: string) => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return { data: { studio_id: 'studio-test-001' }, error: null }
          }
          if (table === 'commission_splits') {
            return { data: splitData ?? { id: 'split-test-001' }, error: null }
          }
          if (table === 'locations' || table === 'studio_locations') {
            return { data: locationData !== undefined ? locationData : { id: 'loc-test-001' }, error: null }
          }
          return { data: { studio_id: 'studio-test-001' }, error: null }
        }),
        single: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return { data: defaultChargeData, error: null }
          }
          return { data: null, error: null }
        }),
      })),
    })),
    update: vi.fn(() => ({
      eq: vi.fn(async () => ({ error: null })),
    })),
  }))

  // Attach .bind() so the bind-cast pattern resolves to a callable (returns fromFn itself)
  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  return {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: fromFn,
  } as unknown as SupabaseServiceClient
}

